    // IsValue reports whether the corresponding expression is a value.
    // Builtins are not considered values. Constant values have a non-
    // nil Value.
    bool rec::IsValue(TypeAndValue tv)
    {
        //Go switch emulation
        {
            auto condition = tv.mode;
            int conditionId = -1;
            if(condition == constant_) { conditionId = 0; }
            else if(condition == variable) { conditionId = 1; }
            else if(condition == mapindex) { conditionId = 2; }
            else if(condition == value) { conditionId = 3; }
            else if(condition == commaok) { conditionId = 4; }
            else if(condition == commaerr) { conditionId = 5; }
            switch(conditionId)
            {
                case 0:
                case 1:
                case 2:
                case 3:
                case 4:
                case 5:
                    return true;
                    break;
            }
        }
        return false;
    }

